import{_ as a,o as t,c as n,a2 as o}from"./chunks/framework.DaGSOal_.js";const f=JSON.parse('{"title":"U","description":"","frontmatter":{},"headers":[],"relativePath":"glossaire-a-z/u.md","filePath":"glossaire-a-z/u.md"}'),r={name:"glossaire-a-z/u.md"};function s(i,e,d,u,l,c){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="u" tabindex="-1">U <a class="header-anchor" href="#u" aria-label="Permalink to &quot;U&quot;">​</a></h1><h2 id="unbonding-fr-periode-de-deblocage" tabindex="-1">Unbonding (fr : Période de déblocage) <a class="header-anchor" href="#unbonding-fr-periode-de-deblocage" aria-label="Permalink to &quot;Unbonding (fr : Période de déblocage)&quot;">​</a></h2><p>Désigne une période pendant laquelle les jetons délégués ou mis en staking ne peuvent pas être immédiatement retirés ou transférés. Alors que de nombreux réseaux à preuve d’enjeu (<em>Proof of Stake</em>, PoS) imposent une période de déblocage, Cardano permet de déléguer des ada sans période de blocage : les jetons restent liquides et transférables à tout moment.</p><h2 id="untyped-plutus-core-uplc-fr-plutus-core-non-type" tabindex="-1">Untyped Plutus Core (UPLC) (fr : Plutus Core non typé) <a class="header-anchor" href="#untyped-plutus-core-uplc-fr-plutus-core-non-type" aria-label="Permalink to &quot;Untyped Plutus Core (UPLC) (fr : Plutus Core non typé)&quot;">​</a></h2><p>Le langage de bas niveau, ou « langage machine », exécuté sur la chaîne par les nœuds Cardano pendant la validation des transactions.</p><h2 id="usdm" tabindex="-1">USDM <a class="header-anchor" href="#usdm" aria-label="Permalink to &quot;USDM&quot;">​</a></h2><p>Un stablecoin indexé sur le dollar américain, émis sur Cardano par Moneta (anciennement Mehen Finance) et adossé à des réserves en dollars américains.</p><h2 id="use-case-fr-cas-d-utilisation" tabindex="-1">Use Case (fr : Cas d’utilisation) <a class="header-anchor" href="#use-case-fr-cas-d-utilisation" aria-label="Permalink to &quot;Use Case (fr : Cas d’utilisation)&quot;">​</a></h2><p>Une application ou un scénario spécifique dans lequel une technologie Cardano permet de résoudre un problème.</p><h2 id="utility-token-fr-jeton-utilitaire" tabindex="-1">Utility Token (fr : Jeton utilitaire) <a class="header-anchor" href="#utility-token-fr-jeton-utilitaire" aria-label="Permalink to &quot;Utility Token (fr : Jeton utilitaire)&quot;">​</a></h2><p>Un type de jeton qui donne accès à des fonctions, des produits ou des services spécifiques au sein d’un réseau blockchain.</p><h2 id="utxo-unspent-transaction-output-fr-sortie-de-transaction-non-depensee" tabindex="-1">UTXO (Unspent Transaction Output) (fr : Sortie de transaction non dépensée) <a class="header-anchor" href="#utxo-unspent-transaction-output-fr-sortie-de-transaction-non-depensee" aria-label="Permalink to &quot;UTXO (Unspent Transaction Output) (fr : Sortie de transaction non dépensée)&quot;">​</a></h2><p>Un modèle de suivi des soldes dans lequel les jetons sont représentés par des sorties de transactions précédentes pouvant être dépensées dans de nouvelles transactions. Cardano étend ce modèle avec sa conception eUTXO (<em>Extended UTXO</em>).</p><h2 id="utxo-cost-per-byte-fr-cout-utxo-par-octet" tabindex="-1">UTxO Cost per Byte (fr : Coût UTxO par octet) <a class="header-anchor" href="#utxo-cost-per-byte-fr-cout-utxo-par-octet" aria-label="Permalink to &quot;UTxO Cost per Byte (fr : Coût UTxO par octet)&quot;">​</a></h2><p>Le paramètre du protocole qui fixe le coût de chaque octet de stockage occupé par un UTxO, utilisé pour déterminer le dépôt minimal requis.</p>',15)])])}const h=a(r,[["render",s]]);export{f as __pageData,h as default};
